--- /dev/null
+++ b/src-tauri/crates/ffmpeg_utils/src/media/workload.rs
@@ -0,0 +1,111 @@
+//! Scheduling intent scoped to one media worker invocation.
+
+/// A caller may mark an export that the user is waiting for. Other media work
+/// (including background recording) inherits the worker's existing policy.
+#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
+pub enum MediaWorkload {
+    #[default]
+    Inherit,
+    UserInitiated,
+}
+
+pub(super) struct WorkloadGuard {
+    #[cfg(target_os = "macos")]
+    previous: Option<(u32, i32)>,
+    // A QoS request must be undone on the originating worker, never another
+    // Tokio thread after an await. This guard only lives in the blocking closure.
+    _thread_affinity: std::marker::PhantomData<std::rc::Rc<()>>,
+}
+
+#[cfg(target_os = "macos")]
+mod darwin {
+    use std::ffi::c_void;
+    unsafe extern "C" {
+        fn pthread_self() -> *mut c_void;
+        fn pthread_get_qos_class_np(
+            thread: *mut c_void,
+            class: *mut u32,
+            relative: *mut i32,
+        ) -> i32;
+        pub(super) fn pthread_set_qos_class_self_np(class: u32, relative: i32) -> i32;
+    }
+    pub(super) fn requested() -> Option<(u32, i32)> {
+        let (mut class, mut relative) = (0, 0);
+        let result = unsafe { pthread_get_qos_class_np(pthread_self(), &mut class, &mut relative) };
+        (result == 0).then_some((class, relative))
+    }
+}
+
+impl MediaWorkload {
+    pub(super) fn enter(self) -> WorkloadGuard {
+        #[cfg(target_os = "macos")]
+        let previous = if self == Self::UserInitiated {
+            // Never lower an existing higher request or change an unspecified
+            // policy, which cannot be restored with pthread_set_qos_class_self_np.
+            darwin::requested()
+                .filter(|&(class, _)| (1..25).contains(&class))
+                .filter(|_| unsafe { darwin::pthread_set_qos_class_self_np(25, 0) } == 0)
+        } else {
+            None
+        };
+        #[cfg(not(target_os = "macos"))]
+        let _ = self;
+        WorkloadGuard {
+            #[cfg(target_os = "macos")]
+            previous,
+            _thread_affinity: std::marker::PhantomData,
+        }
+    }
+}
+
+impl Drop for WorkloadGuard {
+    fn drop(&mut self) {
+        #[cfg(target_os = "macos")]
+        if let Some((class, relative)) = self.previous {
+            let result = unsafe { darwin::pthread_set_qos_class_self_np(class, relative) };
+            if result != 0 {
+                eprintln!("Restore media worker QoS failed: {result}");
+            }
+        }
+    }
+}
+
+#[cfg(all(test, target_os = "macos"))]
+mod tests {
+    use super::*;
+
+    #[test]
+    fn user_workload_restores_the_pool_thread_after_error_and_unwind() {
+        std::thread::spawn(|| {
+            assert_eq!(unsafe { darwin::pthread_set_qos_class_self_np(21, -2) }, 0);
+            let original = darwin::requested();
+            {
+                let _unchanged = MediaWorkload::Inherit.enter();
+                assert_eq!(darwin::requested(), original);
+            }
+            let result = (|| -> Result<(), ()> {
+                let _guard = MediaWorkload::UserInitiated.enter();
+                assert_eq!(darwin::requested(), Some((25, 0)));
+                {
+                    let _nested = MediaWorkload::UserInitiated.enter();
+                }
+                assert_eq!(darwin::requested(), Some((25, 0)));
+                Err(())
+            })();
+            assert!(result.is_err());
+            assert_eq!(darwin::requested(), original);
+            let _ = std::panic::catch_unwind(|| {
+                let _guard = MediaWorkload::UserInitiated.enter();
+                panic!("exercise cancellation/unwind cleanup");
+            });
+            assert_eq!(darwin::requested(), original);
+            assert_eq!(unsafe { darwin::pthread_set_qos_class_self_np(33, 0) }, 0);
+            {
+                let _guard = MediaWorkload::UserInitiated.enter();
+            }
+            assert_eq!(darwin::requested(), Some((33, 0)));
+        })
+        .join()
+        .unwrap();
+    }
+}
